class WorkerBridge {
  constructor(){this.next=0;this.pending=new Map();this.start();}
  start(){
    try{
      this.worker=new Worker(new URL('./worker.js',import.meta.url),{type:'module'});
      this.worker.onmessage=({data})=>{
        const pending=this.pending.get(data.id);if(!pending)return;
        if(data.progress!==undefined){pending.progress?.(data.progress);return;}
        this.pending.delete(data.id);clearTimeout(pending.timer);
        if(data.error){const error=new Error(data.error.message);Object.assign(error,data.error);pending.reject(error);}
        else pending.resolve(data);
      };
      this.worker.onerror=event=>{event.preventDefault();this.abort(new Error(event.message||'Worker failure'));};
      this.error=null;
    }catch(error){this.worker=null;this.error=error;}
  }
  abort(error){
    // A timed-out CPU task must actually stop, not just lose its awaiting promise.
    this.worker?.terminate();this.worker=null;this.error=error;
    for(const pending of this.pending.values()){clearTimeout(pending.timer);pending.reject(error);}this.pending.clear();
  }
  run(type,payload,progress){
    if(!this.worker)this.start();
    if(!this.worker)return Promise.reject(new Error(`Worker unavailable: ${this.error?.message}. Serve the project over localhost.`));
    const id=++this.next;
    return new Promise((resolve,reject)=>{
      const timer=setTimeout(()=>this.abort(new Error(`${type} exceeded its 60-second safety limit; the worker was terminated`)),60000);
      this.pending.set(id,{resolve,reject,progress,timer});
      try{this.worker.postMessage({id,type,payload,revision:state.revision});}catch(error){this.pending.delete(id);clearTimeout(timer);reject(error);}
    });
  }
}
